INSERT INTO books (id,slug,title,subtitle,author,description,access_level,required_plan,status,updated_at) VALUES
  ('bk_humonks','humonks','HUMONKS','A Novel — Draft One, Turn One','Niyaz Rafat','Evolution is a loop, not a line. Monkeys made Humonks. Humonks made humans. Humans forgot.','auth','free','published',datetime('now'));
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_39c307eeea','bk_humonks','epigraphs','Epigraphs','The two lines the novel opens under.','public',1,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f24880d93576','ch_39c307eeea','callout','{"tone": "info", "title": "Draft status", "text": "Draft One — Turn One"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59c210997e63','ch_39c307eeea','quote','{"text": "यो ह्ययं मम लाङ्गूले दीप्यते हव्यवाहनः। अस्य सन्तर्पणं न्याय्यं कर्तुमेभिर्गृहोत्तमैः॥", "cite": ""}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b38ce9287b7a','ch_39c307eeea','quote','{"text": "This fire they have lit upon my tail — it is only right that I should feed it, and these fine houses are what I have.", "cite": "Hanumān, in the burning of Lankā"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d9fb0a37e00','ch_39c307eeea','quote','{"text": "No animal arrives.", "cite": "inscription, Volume One of the Smriti, recovered 1911"}',4);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_dd32742d05','bk_humonks','prologue','Prologue — Subject 4,001','Subject 4,001 walks into the lab having marked his own forehead.','public',2,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_265ea5c39da3','ch_dd32742d05','text','{"text": "The mark went on while they were sleeping."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa57ae3ff249','ch_dd32742d05','text','{"text": "That was the whole of the protocol, and Aditi Sen had come to find it obscene in a way she could not have defended at a conference. Sedate the subject. Mix cadmium red into an odourless, tasteless, non-irritant gel. Apply a single dot high on the brow, above the ridge, in the one place on a body that no hand can feel and no eye can find without help. Let them wake. Let them get bored. Then give them a mirror."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9c3eadeed69','ch_dd32742d05','text','{"text": "If they reached for the mirror, they had seen another animal."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2406bc27b02c','ch_dd32742d05','text','{"text": "If they reached for their own forehead, they had seen themselves."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec67de055773','ch_dd32742d05','text','{"text": "That was all of it. That was the entire apparatus by which the species had decided who was a person. Eighteen months in a human child — sometimes sixteen, sometimes two years, and the parents were always insufferable about the difference. Some apes, sometimes. Elephants, occasionally, and only the ones who had already decided they liked you. Magpies, which had ruined a great many dinner parties."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38102ec1b66f','ch_dd32742d05','text','{"text": "Macaques: never. Not once, in the literature, without months of training, and the trained ones only ever looked like animals performing a trick they had been paid for. They touched the dot the way a waiter touches a menu."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e7d86c951fa','ch_dd32742d05','text','{"text": "Aditi had run the test four thousand times. She had a reputation and two grants and a marriage that had ended, in her opinion, partly because of the honesty the work required of her at home. She had watched three hundred and twelve animals fail in a single season and had gone out afterward and eaten dinner. She was not sentimental. She had simply arrived, somewhere around the three-thousandth subject, at a quiet private position she had never published, which was that the test did not measure what everyone said it measured."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcba57fc2d04','ch_dd32742d05','text','{"text": "It did not measure whether you knew yourself."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e17b8b056a8a','ch_dd32742d05','text','{"text": "It measured whether you cared how you looked."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec6dd70fd28f','ch_dd32742d05','text','{"text": "The lab was on the fourth floor, and the observation room had a window that had been painted shut in 1994 and a chair that had outlived two directors. Aditi came in at seven with her coffee and found the schedule already printed and squared on the desk, which was not how she left things."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc4452bd3672','ch_dd32742d05','text','{"text": "Subject 4,001. 0800. Consent on file."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e72e5ab738c9','ch_dd32742d05','text','{"text": "She read it twice. Consent on file was not a phrase that appeared on her schedules. Animals did not consent. Animals were acquired, housed, enriched, tested and retired, and there was a great deal of paperwork about all of it, and none of the paperwork was called consent."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_606602aa453b','ch_dd32742d05','text','{"text": "She was still holding the sheet when the door opened."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92112441d2e2','ch_dd32742d05','text','{"text": "He came in on two legs and he was wearing a grey shirt with the sleeves turned back twice, and he sat down in the subject’s chair without being asked, which was the first thing that unsettled her, because it meant he knew which chair was the subject’s."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59135dd307f5','ch_dd32742d05','text','{"text": "“Doctor Sen.”"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac50e37fb7a1','ch_dd32742d05','text','{"text": "“I think there’s been a scheduling error.”"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f6ca5432636','ch_dd32742d05','text','{"text": "“There hasn’t.” He arranged himself. He was perhaps sixty, compact, silver at the temples, and he sat with the particular stillness of a man who has been photographed a great deal and has stopped fidgeting on purpose. “You have a mirror behind that panel. You’d like me to be bored for eleven minutes and then you’ll slide it open.”"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfa5a174297e','ch_dd32742d05','text','{"text": "“Who are you?”"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1b0503860db','ch_dd32742d05','text','{"text": "“Someone who read your 2019 paper.” He smiled, and it was a good smile, and she distrusted it immediately for exactly that reason. “The one where you were careful. You had a result and you buried it in the discussion section under three hedges. Four thousand subjects, and on page eleven you said — I’m paraphrasing —” he tipped his head, “self-recognition may be confounded with social attention.”"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eb9865851e3','ch_dd32742d05','text','{"text": "Aditi did not sit down."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64694ed3ac91','ch_dd32742d05','text','{"text": "“You put it in a subordinate clause,” he said. “It should have been the title.”"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b235faa433a5','ch_dd32742d05','text','{"text": "“You’re not a subject.”"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91789abcba0f','ch_dd32742d05','text','{"text": "“I’m a subject if I’ve consented.” He touched his own forehead then, lightly, with two fingers, exactly where the mark would have gone, and he held them there a moment so she would see. “I did it myself this morning. Cadmium red. I had to order it. It’s a nuisance to get hold of.”"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91fb532cc6ce','ch_dd32742d05','text','{"text": "The room was very quiet. Somewhere below, a trolley went over a threshold strip."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_538c22465a36','ch_dd32742d05','text','{"text": "“That defeats the test,” she said."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81461c2b359b','ch_dd32742d05','text','{"text": "“Yes.” He put his hand down. “That’s what I came to tell you.”"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da5d65cfc58c','ch_dd32742d05','text','{"text": "She was aware of her heart, and of the fact that she was being managed, and that being aware of it was not helping."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a6289ace315','ch_dd32742d05','text','{"text": "“Doctor,” he said, “here is the question I would like to put to you, and then I’ll go, and you can have the room back. When your macaque touches the glass instead of his head — what has he failed to understand?”"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5ebb7335192','ch_dd32742d05','text','{"text": "“That the reflection is him.”"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f72b3ad61a6','ch_dd32742d05','text','{"text": "“Are you sure? Or has he simply understood that there is another animal in the room, and made the entirely reasonable decision to look at it rather than at himself?” He let that sit. “Because that’s what I would do. That’s what anyone would do. The only creature who ignores a stranger in order to check its own face is a creature that has already learned it will be judged. Your test doesn’t find self-awareness. It finds shame.”"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dea6dd840f2','ch_dd32742d05','text','{"text": "“That’s a nice sentence.”"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aebaca672a46','ch_dd32742d05','text','{"text": "“It’s a true one. The nice ones usually are, which is how they get away with it.” He stood. “You’ve run four thousand of these.”"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_faf8733ddf37','ch_dd32742d05','text','{"text": "“Four thousand and eleven.”"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40140e07585b','ch_dd32742d05','text','{"text": "“And never on yourself.”"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_464d3c68a901','ch_dd32742d05','text','{"text": "She did not answer that."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_810c17ff53d4','ch_dd32742d05','text','{"text": "At the door he paused, one hand on the frame, and she noticed then — she would think about this for a long time afterward, at two in the morning, for years — that he was wearing gloves. Thin ones. Indoors, in August, in a building with no air conditioning to speak of."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4e438af9151','ch_dd32742d05','text','{"text": "“They’ll tell you a story about my people,” he said. “Some of it will be true. When you hear it, I’d like you to remember that you and I have exactly the same problem in front of a mirror. Only one of us has been asked to prove it.”"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3bd23f1f175','ch_dd32742d05','text','{"text": "Then he was gone, and the corridor swallowed the sound of him very fast, the way corridors do."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08eaf0af37d0','ch_dd32742d05','text','{"text": "She wrote it up because she wrote everything up. That was the habit and the habit was the whole of her character."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a80b9cce19e','ch_dd32742d05','text','{"text": "Subject 4,001. Mark: self-applied (protocol void). Duration to mirror: n/a. Result:"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99ab4b789cf3','ch_dd32742d05','text','{"text": "She sat with the cursor in that field for a long time. Then she saved the file with the field empty, and shut the machine, and went home, and stood in her own bathroom at half past eleven with the tap running for no reason at all."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aefae9a17ba8','ch_dd32742d05','text','{"text": "She did not look up."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb32a3103659','ch_dd32742d05','text','{"text": "She has never been able to explain, since, whether that was an answer or an evasion, and she is the leading authority in the country on the difference."}',43);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_7d73144747','bk_humonks','chapter-one','Chapter One — Salt and Weight','Nine days, six stones, and a sea that has not risen by a fingernail.','auth',3,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c193e7a39ec','ch_7d73144747','callout','{"tone": "info", "title": "Turn One", "text": "The Hand That Built"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f9cef457423','ch_7d73144747','text','{"text": "The sea had eaten nine days of work and was not yet full."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f61c1bd37826','ch_7d73144747','text','{"text": "Vakra stood at the tide-line with the water running warm over his feet and watched them do it again. Four rafts lashed abreast, thirty men and twice as many of his own kind on the ropes, and slung between the rafts in a cradle of green vine a block of grey coastal granite the size of a grain-cart. It had taken a day and a night to bring it down from the escarpment. It had taken eleven men to dress its faces flat. Someone had carved a sun on the top of it, which struck Vakra as optimistic."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b59ca39e8be','ch_7d73144747','text','{"text": "The drum went. The cradle released."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39e2cdab6dbc','ch_7d73144747','text','{"text": "The stone did not so much fall as depart. It went through the surface without argument and without splash, the way a word goes out of a room, and the rafts leapt up behind it and slammed down again, and the vine ropes came whipping back and took a man off the second raft and into the water, and everyone shouted, and by the time they had him out by the arms the stone was gone entirely, and there was nothing at all to look at."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45aa8dabbfd7','ch_7d73144747','text','{"text": "Nine days. Six stones. A sea that had not risen by the thickness of a fingernail."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_110e7c3d69fe','ch_7d73144747','text','{"text": "Beside him, a young Humonk called Puṭa said, “We’ll be here at the end of the world.”"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e7a8ea5e57a','ch_7d73144747','text','{"text": "“We’ll be here longer than that,” Vakra said. “The world will end and they’ll still be dropping rocks in the sea.”"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d70ceed5bfee','ch_7d73144747','text','{"text": "Puṭa laughed. He was nineteen and he laughed at almost everything, which was going to be a problem for him later, because the humans had begun to notice that they could not tell what his laughing meant."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7652a7aa9c02','ch_7d73144747','text','{"text": "The camp went four miles up the shore and it stank magnificently. Fifty thousand mouths and no sanitation worth the name, and over it all the sweet rot of cut vine, because everything in the world was being made of vine that season. There were three kinds of people in it and they slept in three separate arrangements and nobody had ever announced this or written it down."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_913fe93c9bde','ch_7d73144747','text','{"text": "The humans slept in rows, in tents, by unit, with their gear stacked at their feet."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b78dd1c7298','ch_7d73144747','text','{"text": "The vanara slept in trees where there were trees and in heaps where there were not, and they woke all at once at any sound, which the humans found unnerving and had learned not to say so."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0102b9763435','ch_7d73144747','text','{"text": "And Vakra’s people slept in the gaps. Under the carts. Along the sea-wall. Wherever there was a shape of ground that nobody had put to use, some of his people had found it and made it theirs, and this was not by arrangement either. It was simply what happened when there was no place made for you: you became very good at finding places."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be2250cdb479','ch_7d73144747','text','{"text": "He had been at the shore for two months. In that time he had been asked four questions. He had counted them, which he understood was not a healthy thing to count."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec8db229020c','ch_7d73144747','text','{"text": "The engineers met at dusk under a stretched hide, and Vakra was there because someone had to carry the stone samples and he had made himself the person who carried the stone samples."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c07b42d1c464','ch_7d73144747','text','{"text": "There were eleven of them. Nala at the head — grey-gold, enormous through the chest, with the flat unhurried voice of a man who has never in his life had to raise it — and around him a handful of vanara foremen, and three human wrights out of Kosala who had come south with the prince’s party and had not stopped being astonished by anything since."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a8989c016bb','ch_7d73144747','text','{"text": "The chief of the wrights was called Devadatta, and Vakra had decided in the first week that he liked him, and had been annoyed with himself about it ever since."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87d8dbad7b98','ch_7d73144747','text','{"text": "Devadatta was somewhere past forty and burnt to the colour of old brick and he had a habit, when he was thinking, of pressing his thumb into the bridge of his nose as though holding a door shut. He had brought with him from the north a set of bronze dividers, a plumb-line, three assistants and a book. The book was the thing. It was the first book Vakra had ever seen up close: forty leaves of palm strung on a cord, and on them, in a small furious hand, everything. Every stone. Every rope. Every man. Every load, every failure, every day."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abeddb2717cc','ch_7d73144747','text','{"text": "“Granite is finished,” Devadatta was saying. “I’ll say it plainly so nobody has to say it for me. Six stones, nine days, no bottom. There’s no bottom to find. We are dropping the mountain into a hole and the hole is the sea.”"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fda311d0622a','ch_7d73144747','text','{"text": "“Then we go wider,” said one of the foremen. “More rafts, more stones at once —”"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c04e916e509e','ch_7d73144747','text','{"text": "“More stones at once sink at once.”"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86300c267df7','ch_7d73144747','text','{"text": "“Timber, then.”"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a89603a09b0e','ch_7d73144747','text','{"text": "“Timber’s been tried.” Devadatta didn’t look up from the book. “Timber floats and timber walks. We put down eight hundred spans of decked timber in the third week and the sea took it up the coast overnight and gave it back to us in pieces on somebody else’s beach. The sea doesn’t want a road. The sea has opinions.”"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_556f41406df2','ch_7d73144747','text','{"text": "“The sea,” said Nala mildly, “will be spoken to.”"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1fa4d35ee3a','ch_7d73144747','text','{"text": "There was a silence of the specific kind that follows a remark nobody is willing to be the first to disagree with."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9668d147f39b','ch_7d73144747','text','{"text": "Vakra was standing at the edge of the hide with a basket of rock chips on his hip and no reason at all to speak, and he heard himself say, “You’re arguing with the wrong thing.”"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22c54d532ff9','ch_7d73144747','text','{"text": "Every head came round."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e82a43fa4e8','ch_7d73144747','text','{"text": "It was not that they were angry. That would have been easier. It was that they were surprised, in the way one is surprised by furniture."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_357da11e0b17','ch_7d73144747','text','{"text": "Nala said, “Say that again.”"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2729bc95fe6','ch_7d73144747','text','{"text": "He should have stopped. He had never once in his life managed to stop."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac6258b7fe75','ch_7d73144747','text','{"text": "“You’re arguing with the sea,” Vakra said. “The sea isn’t doing anything. The sea is only sitting there being what it is. The thing that’s beating you is the stone.” He set the basket down because his hands had started to want something to do. “You keep choosing the stone first and then asking the sea to make an exception for it. Choose the sea first. Then find a stone it will agree to.”"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_627211593f3a','ch_7d73144747','text','{"text": "Devadatta had lifted his thumb off the bridge of his nose."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9b1e23ef483','ch_7d73144747','text','{"text": "“There is no stone the sea agrees to,” a foreman said. “That’s what stone is.”"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd9f70a56fa6','ch_7d73144747','text','{"text": "“No,” said Vakra. “That’s what granite is.”"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_197150ac72b3','ch_7d73144747','text','{"text": "He crouched and turned the basket out onto the sand and the chips went everywhere, and he picked them up one at a time and struck each one with the second knuckle of his good hand and set them in a line as he went."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65cd138cef69','ch_7d73144747','text','{"text": "Tok. Grey shore-granite. Dense, dull, a sound that stopped where it started."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87589c07d774','ch_7d73144747','text','{"text": "Tok. Same."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0dc0d71792d','ch_7d73144747','text','{"text": "Tak. Something paler, with a grain. Slightly livelier."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_495ca7eb9e96','ch_7d73144747','text','{"text": "He worked down the line and the arguing above his head thinned out and then stopped, because there is something about a man doing a small precise thing in silence that empties a room."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97459c42652e','ch_7d73144747','text','{"text": "“How are you doing that,” said Devadatta."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0fbf913f4f7','ch_7d73144747','text','{"text": "“Doing what.”"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45162e705012','ch_7d73144747','text','{"text": "“You’re sorting them by weight. You haven’t weighed anything.”"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79044a4671b5','ch_7d73144747','text','{"text": "“I’m not sorting them by weight.” Vakra held one up. “Weight is a thing a stone has because of how big it is. That’s no use to you. A big light stone and a small heavy stone can weigh the same and one of them will float and one of them won’t. What you want to know is how much stone is in the stone.” He knocked it again. “It tells you. If it rings, there’s air in it. If it stops, there isn’t.”"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46f7965b1e70','ch_7d73144747','text','{"text": "“That’s —” Devadatta stopped. He looked at his book, and then at Vakra, and then, briefly and with a strange embarrassment, at his own hand. “That’s density.”"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5019d76dac6','ch_7d73144747','text','{"text": "“If that’s your word for it.”"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3e8562d8d70','ch_7d73144747','text','{"text": "“How long have you known that?”"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4bb192998f2','ch_7d73144747','text','{"text": "Vakra thought about it, honestly, because he was being asked a question, and it was the fifth."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2d3bafef05b','ch_7d73144747','text','{"text": "“Since I was six,” he said. “It isn’t clever. Everyone in my valley knows it. You have to know it, or you carry the wrong rock uphill and then you’ve spent your morning.”"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb6511a4c65c','ch_7d73144747','text','{"text": "Afterward, when the others had gone up to the fires, Devadatta stayed under the hide with a lamp and untied the cord on his book, and Vakra stayed because he had not been dismissed and did not know whether being dismissed was a thing that happened to him."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_830ddd6662ac','ch_7d73144747','text','{"text": "“I need your name for the record,” Devadatta said."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c3143f78d7c','ch_7d73144747','text','{"text": "“Vakra.”"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26ba2ca0a63a','ch_7d73144747','text','{"text": "“Vakra.” He wrote it. It took him no time at all, which struck Vakra as remarkable — that a person could be reduced to a mark that fast. “Vakra, of?”"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f10e8b927ef','ch_7d73144747','text','{"text": "“Of nowhere. Of the coast.”"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62b2d29b55ed','ch_7d73144747','text','{"text": "“You have to be of something. The column wants a place.”"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94175efbf2b5','ch_7d73144747','text','{"text": "“Then put the coast.”"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d2d6b2de088','ch_7d73144747','text','{"text": "Devadatta wrote it and then sat looking at the page with the pen not moving."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e63af5c7be8b','ch_7d73144747','text','{"text": "“There’s a difficulty,” he said. “I’ve fourteen columns here and they’re all wrong for you. I have men, which is my own people. I have vanara, which is the host. I have bearers, which is anyone carrying. And you’re none of those, and I know you’re none of those, because I’ve watched you for two months and you have never once carried something without first deciding whether it was worth carrying.” He rubbed the bridge of his nose. “I don’t have a number for you.”"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71242c24111c','ch_7d73144747','text','{"text": "Vakra said nothing."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f72f2885596','ch_7d73144747','text','{"text": "“It’s a small thing,” Devadatta said, “but it isn’t nothing, and I’d like you to know that I know it. Rations come off these columns. Water comes off these columns. If a man isn’t in a column he is fed by somebody’s kindness, and kindness is not a system, and it fails on the days when everyone is tired.”"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b547c90cd3b','ch_7d73144747','text','{"text": "“We’ve been fed.”"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f23bf2c339c','ch_7d73144747','text','{"text": "“You’ve been fed by guess.” He said it with real disgust, and the disgust was for himself, and that was the moment — Vakra would think about this for the rest of his life, in the way you think about the small door you did not notice you were walking through — that was the moment he decided Devadatta was a good man."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90a9ae535cfe','ch_7d73144747','text','{"text": "“I’ll make you a column,” Devadatta said. “I’ll do it properly. You’ll be counted.”"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f836238573d','ch_7d73144747','text','{"text": "“All right.”"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb9b05671c8a','ch_7d73144747','text','{"text": "“You don’t sound pleased.”"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5612a7e93575','ch_7d73144747','text','{"text": "Vakra looked out at the water, which had gone the colour of wet slate, and somewhere far out on it, under nine days of it, six dressed stones with a sun carved on one of them lay in the dark being no use to anybody."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5302b5ae4d2d','ch_7d73144747','text','{"text": "“I’ve never been counted,” he said. “I don’t know yet what it’s for.”"}',66);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_c86b4a13ed','bk_humonks','chapter-two','Chapter Two — The Stone That Drinks','The stone everyone on the coast uses to scrub their heels.','auth',4,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7981907e7196','ch_c86b4a13ed','text','{"text": "Ilā arrived on the eleventh day with a split lip and a raider’s cord round her arm and an opinion about everything she had seen on the way down."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_998b8cd12b42','ch_c86b4a13ed','text','{"text": "“They’ve got you sorting gravel,” she said."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ed759ace4b8','ch_c86b4a13ed','text','{"text": "“I’m not sorting gravel.”"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3fabf9fa307','ch_c86b4a13ed','text','{"text": "“You’re sitting in sand with a basket. I’ve come four hundred miles and my brother is sitting in sand with a basket.” She dropped down beside him, all knees and elbows, and stole his water without asking, and Vakra felt the specific unclenching that happens when the only person who has ever seen you clearly walks into a place where nobody has."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d852e4cea9c','ch_c86b4a13ed','text','{"text": "“How is your lip.”"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56c1dd97b74b','ch_c86b4a13ed','text','{"text": "“A man in Kishkindha said something about my hands.”"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_773755f9cd56','ch_c86b4a13ed','text','{"text": "“And?”"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a4f91a84d59','ch_c86b4a13ed','text','{"text": "“And now he says less.” She wiped her mouth. “How long are they going to keep dropping mountains in the water?”"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b9d71941e2e','ch_c86b4a13ed','text','{"text": "“Until someone stops them.”"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5dcc0fd8c8e','ch_c86b4a13ed','text','{"text": "“Then stop them.”"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30a20a699df8','ch_c86b4a13ed','text','{"text": "“I’m working on it.”"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_826b1259663e','ch_c86b4a13ed','text','{"text": "“Vakra.” She turned and looked at him and her white blaze caught the light. “You’re not working on it. You’ve solved it. You solved it the day you got here, I can hear it in your voice, and you’ve spent eleven days waiting for someone to ask you nicely.”"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4414272a2a0b','ch_c86b4a13ed','text','{"text": "He didn’t answer, because there was no answer to that which was not simply yes."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdb90252e568','ch_c86b4a13ed','text','{"text": "The stone was called float-stone and there was nothing secret about it."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5adb4e659c7','ch_c86b4a13ed','text','{"text": "It came out of the old fire-hills eighty miles down the coast, and it was pale and it was ugly and it was full of holes, and children on that coast used it to scrub their heels. It weighed nothing. You could pick up a piece the size of a dog and carry it home under one arm. It was the joke stone. It was the stone that was no use for anything, because you could not build with it, you could not sharpen on it, and you could not sling it — it went nowhere, it was all bluster and no arrival."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_361952c95698','ch_c86b4a13ed','text','{"text": "And it floated."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0ec413ddcd2','ch_c86b4a13ed','text','{"text": "Everyone on that coast knew it floated. It was not knowledge. It was weather."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f95897e3ad1a','ch_c86b4a13ed','text','{"text": "What Vakra knew, and what he had never had reason to say aloud until a sea got in the way, was why — or at least the shape of why, which is all anyone ever really has. He had broken a hundred pieces of it as a boy. Inside, it was not stone the way granite is stone. Inside it was foam. It was a lattice of hollows, a stone made entirely of the shape of the air that had been in it while it cooled, and the air had never left."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5083d996867','ch_c86b4a13ed','text','{"text": "It was a stone that had kept its own breath."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_244dfeab6090','ch_c86b4a13ed','text','{"text": "The problem was not the stone. The problem was that it was the heel-scrubbing stone, and he was the man in the sand with the basket, and those two facts multiplied."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cd7c99f01af','ch_c86b4a13ed','text','{"text": "He tried Nala first, because that was the order of things."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc81c3a9656f','ch_c86b4a13ed','text','{"text": "He found him at the north end at first light, standing in the shallows looking out, alone, which was rare. Nala listened without interrupting for the whole of it, which took some time, and when Vakra finished he was quiet for a while."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b32fc384363','ch_c86b4a13ed','text','{"text": "“Float-stone,” he said."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_644bf65b433f','ch_c86b4a13ed','text','{"text": "“Yes.”"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f1986d4a165','ch_c86b4a13ed','text','{"text": "“The scrubbing stone.”"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b975c4a76628','ch_c86b4a13ed','text','{"text": "“Yes.”"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed3687c3ca5c','ch_c86b4a13ed','text','{"text": "“You’d have me carry an army across the sea on the scrubbing stone.”"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea0a6b2d9a7d','ch_c86b4a13ed','text','{"text": "“I’d have you test it,” Vakra said, and heard his voice come out wrong, too fast, too much want in it. “That’s all. One raft-load. Two days’ hauling. If I’m wrong, you’ve lost two days out of nine that are already lost.”"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_779a8fa9bb17','ch_c86b4a13ed','text','{"text": "Nala turned. He was very large up close, in a way that was easy to forget when he was speaking mildly at a table, and there was nothing unkind in his face at all."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_643fd0c9eacd','ch_c86b4a13ed','text','{"text": "“Do you know what it costs to be wrong here?” he said. “Not for you. For me. There are fifty thousand men on this beach and every one of them is watching to see whether the monkey can build the road. That’s the whole of it, that’s the entire question, and every day I don’t have an answer the answer starts to be no.” He looked back out at the water. “If I go to the prince and say, I will float your army on the stone your daughters clean their feet with, and it fails — it will not be a plan that failed. It will be us that failed. Do you understand the difference?”"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00f348c414f6','ch_c86b4a13ed','text','{"text": "“Yes,” said Vakra."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71fd854ae8e1','ch_c86b4a13ed','text','{"text": "“I don’t think you do. It’s the only thing I think about.”"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0b7bb5225ca','ch_c86b4a13ed','text','{"text": "“I understand it exactly,” Vakra said, “because it is the reason nobody has asked me anything for two months.”"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e62fcb595793','ch_c86b4a13ed','text','{"text": "And that landed. He watched it land. Nala’s jaw moved once."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a34806959a0','ch_c86b4a13ed','text','{"text": "“Bring it to the wrights,” he said at last. “Not to me. If a human says it, it’s engineering. If I say it, it’s a monkey’s idea. That is not a thing I made and it is not a thing I can unmake this week.” He started up the beach. Then, without turning: “You should have come to me on the first day.”"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7770d72a7928','ch_c86b4a13ed','text','{"text": "“I did,” said Vakra."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bea52432905','ch_c86b4a13ed','text','{"text": "Nala stopped for perhaps the length of a breath."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbc95e2f093c','ch_c86b4a13ed','text','{"text": "Then he went on up the beach, and Vakra stood in the shallows and understood, with a clarity that arrived like cold water, that he had just been told something true by a man who had chosen not to remember it."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d7540952c26','ch_c86b4a13ed','text','{"text": "He did it with a bowl."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d19f38df4a2','ch_c86b4a13ed','text','{"text": "That was Ilā’s idea, and it was a better idea than any of his, and he told her so, and she said obviously, and stole his water again."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89ab68be772b','ch_c86b4a13ed','text','{"text": "He waited until the engineers had assembled under the hide and the arguing had reached the flat exhausted stage where anything new is a mercy. Then he walked in with a wide clay bowl of seawater in both hands and set it in the middle of the mat, and knelt, and put down beside it two stones of exactly the same size."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68604bb0605f','ch_c86b4a13ed','text','{"text": "Nobody said anything, because he had not asked anything."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a16b68726345','ch_c86b4a13ed','text','{"text": "He picked up the first stone, the grey one, and held it out flat on his palm so they could all see it, and dropped it in."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1480ad53d41f','ch_c86b4a13ed','text','{"text": "It went down and hit the clay with a knock and sat there."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7551b71d5635','ch_c86b4a13ed','text','{"text": "He picked up the second, the pale ugly one with the holes in it, and held it out the same way, and let them look at it long enough to be sure it was a stone, and dropped it in."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8c4b67942dd','ch_c86b4a13ed','text','{"text": "It went under. Every man there watched it go under."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5933fda8716b','ch_c86b4a13ed','text','{"text": "Then it came back up, and turned once, and sat on the surface of the water like something alive, and stayed."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62cf8395fe4d','ch_c86b4a13ed','text','{"text": "Somebody said, very quietly, “Oh.”"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd47c1c595f2','ch_c86b4a13ed','text','{"text": "Devadatta put his hand into the bowl and pushed it down and it came up again. He did it three times. On the third he laughed out loud — a short, undignified bark of a laugh, entirely involuntary, the laugh of a man watching the world be more interesting than he had budgeted for."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17b6bc727e42','ch_c86b4a13ed','text','{"text": "“What is that.”"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ef796c0a3cb','ch_c86b4a13ed','text','{"text": "“Float-stone,” said Vakra. “It’s the stone you scrub your heels with.”"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff93eef24d1b','ch_c86b4a13ed','text','{"text": "“Where does it come from?”"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8c1d6da1502','ch_c86b4a13ed','text','{"text": "“Eighty miles south. There’s a valley of it. There’s more of it than we could use in ten years.”"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8c9061ea082','ch_c86b4a13ed','text','{"text": "“Why does it float?”"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f52ea9615e1','ch_c86b4a13ed','text','{"text": "“Because it’s full of the breath it was made in,” said Vakra, “and the breath never got out.”"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81189213c43d','ch_c86b4a13ed','text','{"text": "There was a long silence under the hide, and it was not the earlier kind. It was the good kind. It was the silence of eleven exhausted men all doing arithmetic at once."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc2261f2c60d','ch_c86b4a13ed','text','{"text": "“It won’t take a load,” said one of the foremen. “Not on its own. It’ll crumble under a cart.”"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03add1f4a38d','ch_c86b4a13ed','text','{"text": "“No,” said Vakra, and he had been waiting eleven days to say this part, and it came out steady. “Not on its own. On its own it’s a float. You don’t build the road out of it — you build the road on it. Timber decks, lashed. The float-stone underneath in cribs, netted, so it can’t wander. The stone holds the deck up and the deck holds the stone down and neither of them can leave.” He looked around at them. “The sea doesn’t have to agree. It only has to be underneath.”"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a188e789d23e','ch_c86b4a13ed','text','{"text": "Devadatta had already untied his book."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07ed684be0e0','ch_c86b4a13ed','text','{"text": "It is worth setting down exactly what happened next, because it is the thing that made everything afterward."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_360b5d6a0a78','ch_c86b4a13ed','text','{"text": "Devadatta wrote for some time, quickly, in his small furious hand, and the others talked over the top of him — cribs, netting, the depth of the decks, how many rafts to send south and how fast. Vakra was asked four questions in as many minutes, which was as many as he had been asked in the previous two months, and he answered all four, and the answering was the best hour of his life to that point."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bd75a2a6952','ch_c86b4a13ed','text','{"text": "Then Nala arrived, having been sent for, and Devadatta stood up with the book in his hand and said, “We have it. Float-stone. In cribs, under decking. It’ll carry.”"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa7a15e9559e','ch_c86b4a13ed','text','{"text": "And Nala looked at the bowl, and at the pale stone sitting on the water, and something went across his face very fast."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ead2b7c4c4f6','ch_c86b4a13ed','text','{"text": "“Yes,” he said. “Yes — that’s the shape of it.”"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12c14832a4ba','ch_c86b4a13ed','text','{"text": "And Devadatta wrote, in the column for the origin of the work, and Vakra read it upside down across the mat because he had spent two months learning to read upside down across mats:"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8696d73cbb6','ch_c86b4a13ed','text','{"text": "NALA. Float-stone. Cribbed under deck."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5750d02de090','ch_c86b4a13ed','text','{"text": "It was not a lie. Nobody had lied. Devadatta had asked no question and Nala had told no untruth and everyone under that hide had been in the room. It was simply that the pen had been in a particular hand, and the hand had reached for the name it already knew, and there was no moment at which anyone could have said wait, because the moment was one heartbeat wide and by the time you noticed it you would have been interrupting."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28c8b4151d76','ch_c86b4a13ed','text','{"text": "Vakra opened his mouth."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e6e5cbfdfa5','ch_c86b4a13ed','text','{"text": "Then Devadatta looked up at him with an expression of open, uncomplicated delight and said, “You’ve won us the war, do you know that? You in the sand with your basket,” and it was so kind, and it was so warm, and it was the first time in two months that a man had looked at him like that."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a46ff154a99b','ch_c86b4a13ed','text','{"text": "And Vakra closed his mouth, and smiled, and said, “It’s only a stone.”"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95f4d2f9ef69','ch_c86b4a13ed','text','{"text": "Ilā found him afterward at the tide-line, and looked at his face for about two seconds."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07d2471b37bc','ch_c86b4a13ed','text','{"text": "“What did they do.”"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fa83d45f931','ch_c86b4a13ed','text','{"text": "“Nothing. They took it. It’s happening. Rafts go south at dawn.”"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56f5629a924e','ch_c86b4a13ed','text','{"text": "“Vakra.”"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e722c6a3213b','ch_c86b4a13ed','text','{"text": "“It’s happening, Ilā. That’s the thing that matters. Three months from now there’ll be a road on this water because I knocked a rock and heard a hole in it, and it does not matter one grain of sand whose name is on the leaf.”"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b51ebd086080','ch_c86b4a13ed','text','{"text": "She looked at him for a long moment. Then she held up her right hand in the last of the light, the ring finger short by two joints, white and blunt at the end."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1d65b83597f','ch_c86b4a13ed','text','{"text": "“You know how I lost these.”"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cf2ae1c1c90','ch_c86b4a13ed','text','{"text": "“A cart.”"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43209cc4de58','ch_c86b4a13ed','text','{"text": "“That’s what I told you. That’s what I’ve told everybody.” She turned the hand over. “I lost them in Kishkindha when I was fourteen, holding a rope on a stone-lift, and the human foreman on the other end let go early because he wanted his meal, and when I screamed he said — and he wasn’t even cruel, Vakra, that’s the part, he wasn’t angry — he said, it’s all right, you’ve got the other one.” She lowered the hand. “It doesn’t matter whose name is on the leaf. You’re right. It matters whose name is on the leaf the next time, and the time after that, and in three hundred years when they’ve forgotten there was ever a bowl or a basket or a brother of mine sitting in the sand.”"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff4cb2ea3462','ch_c86b4a13ed','text','{"text": "“Ilā —”"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3246f086555','ch_c86b4a13ed','text','{"text": "“They’ll build a road across the sea,” she said, “and one day somebody will look at it and say, how in the world did men do that.”"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74cd663d4194','ch_c86b4a13ed','text','{"text": "She walked off up the beach."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32aac51186a8','ch_c86b4a13ed','text','{"text": "He stayed. The tide came in over his feet, warm, and went out again, and did not care."}',83);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_abb4d013c3','bk_humonks','chapter-three','Chapter Three — Still Water','Flat water, three miles out, and a hand that does not go to the surface.','auth',5,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0e0bc5aa220','ch_abb4d013c3','text','{"text": "The road took eleven weeks."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27e5e3e983cb','ch_abb4d013c3','text','{"text": "It went out from the shore in a slow pale line, and it was not beautiful. That was the thing nobody afterward would ever get right. It was a low ugly raft of a thing, three carts wide, riding almost flush with the water so that in any swell it went under and came back, and men crossing it in the second month said it was like walking on the back of something asleep. It smelt of cut vine and wet rope and the strange dry mineral smell of the float-stone, which never went away, and which for the rest of Vakra’s life would be the smell of being useful."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6c4218faef2','ch_abb4d013c3','text','{"text": "Fourteen thousand worked on it. About nine thousand of those were vanara. About two thousand were his own."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6a8c527da33','ch_abb4d013c3','text','{"text": "And in the seventh week, Devadatta made them a column."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ac3a0036b59','ch_abb4d013c3','text','{"text": "He came down to the crib-yards himself to explain it, which nobody had asked him to do, and which was in its way the most decent thing any human did in the whole of that war."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afdd1515f43f','ch_abb4d013c3','text','{"text": "“It’s ochre,” he said. “It’s in oil so it won’t come off in the water, and it’ll wear away in about a month and we’ll do it again. It goes here.” He touched his own forehead, high, above the ridge, the flat of two fingers. “One dot. That’s all. It’s not a rank and it’s not a mark of any other kind, I want that understood, I’ll say it to every gang myself if I have to.”"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00af98e6bbab','ch_abb4d013c3','text','{"text": "“What’s it for,” said Puṭa."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6bcd77054ac','ch_abb4d013c3','text','{"text": "“It’s for the ledger.” Devadatta held up the book, and by then it was three books. “There are two thousand of you and I cannot tell you apart, and that is my failing and not yours, and I have tried for four months and I cannot do it. So the rations go out by guess and the guess is wrong about a third of the time, and I know it’s wrong because I can count what goes out and count what comes back and the difference is somebody’s dinner.” He put the book down. “With the mark, I can count you at the gate. Counted men get fed. That’s the whole of it. That’s the entire scheme.”"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81ff85bd6719','ch_abb4d013c3','text','{"text": "There was a certain amount of muttering, but not much, because it was true, and because they were hungry, and because he had come down himself."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c85dbc47c561','ch_abb4d013c3','text','{"text": "Vakra took his in the second rank. The finger was warm. It pressed once, above the ridge, and the man moved on."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97f4a2c907e0','ch_abb4d013c3','text','{"text": "“That’s you counted,” said Devadatta, further down the line, to somebody else. “That’s you in the book.”"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b9f113ab67c','ch_abb4d013c3','text','{"text": "They finished on a Tuesday, in the afternoon, without ceremony, because the last crib went in while half the yard was at the water-barrels and by the time anyone noticed there was nothing left to do the thing was simply done."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f66872308eb5','ch_abb4d013c3','text','{"text": "The host began crossing at dawn."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b85efbd7bdff','ch_abb4d013c3','text','{"text": "Vakra did not cross. He was not a soldier and there was no column for him on the far side, and besides, somebody had to stay at the shore end and watch the cribs, because the cribs were his and he had built himself into a job that could not be given away."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de9b3ae2ba34','ch_abb4d013c3','text','{"text": "So he watched it from the beach: fifty thousand men and monkeys going out across the water on a pale road that should not have been there, four abreast, all morning, all afternoon, and into the dark with torches, and still going at midnight, a line of lights out into the black sea like a seam of something molten."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6aef51a7827b','ch_abb4d013c3','text','{"text": "Ilā crossed in the third wave. She came past him at a jog with her raider’s cord on and her spear across her back and she did not stop, but she hit him on the shoulder hard enough to bruise as she went by, and shouted something over the noise that he did not catch and has never stopped trying to reconstruct."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0148abbff65d','ch_abb4d013c3','text','{"text": "He watched until he couldn’t tell the lights from the stars."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ef6f2721a92','ch_abb4d013c3','text','{"text": "Then everyone was gone, and the beach was the emptiest place in the world, and he was alone with fourteen thousand people’s rubbish and a road to nowhere he cared about."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0a5ee1f8795','ch_abb4d013c3','text','{"text": "Three days later he went out onto it to check the seventh crib, because the seventh crib had been settling."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e263328da6ed','ch_abb4d013c3','text','{"text": "The morning was dead calm. There was no swell at all, and no wind, and the sea on the lee side of the road had gone completely flat — flatter than he had ever seen water, a grey-silver sheet with the sky sitting on it whole, so that the clouds were down there too and the whole thing had the quality of a held breath."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbfff3d9ff57','ch_abb4d013c3','text','{"text": "He knelt on the deck at the seventh crib and leaned over the edge to look at the netting."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67fd550ddbe5','ch_abb4d013c3','text','{"text": "And there was a face in the water looking back up at him."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f34b5cad3e7b','ch_abb4d013c3','text','{"text": "He knew what it was. He was thirty-four years old and had lived by the sea his entire life and he had seen his own reflection ten thousand times, in rivers and rain-barrels and the polished side of a copper pot. He knew what a reflection was in the way that everyone knows what a reflection is, which is to say completely, and not at all."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6004dc2f64e9','ch_abb4d013c3','text','{"text": "It was a Humonk. Grey-brown, going white at the shoulders. Left arm carried wrong. A blunt, tired, unremarkable face of the kind that fourteen thousand people had walked past for eleven weeks without once being obliged to hold in mind."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f98f80a97a33','ch_abb4d013c3','text','{"text": "And on its forehead, high, above the ridge, a small round dot of ochre."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da4547d116e6','ch_abb4d013c3','text','{"text": "He looked at it."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9a3a2846e25','ch_abb4d013c3','text','{"text": "He was still, in a way he had not been still since the day he arrived, and the flat water was still, and out beyond the reef nothing moved at all."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a014e31593d','ch_abb4d013c3','text','{"text": "It’s for the ledger, he thought. Counted men get fed."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb0db67c0388','ch_abb4d013c3','text','{"text": "That’s you in the book."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2789b250b7ad','ch_abb4d013c3','text','{"text": "And he thought, with the specific slow horror of a thought arriving that cannot afterward be sent away: no. That is not a mark that tells them who I am. That is a mark that tells them how many of me there are."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17af5aa0b4d9','ch_abb4d013c3','text','{"text": "They did not learn my face. They put a dot on it so they would not have to."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f13a58c7439f','ch_abb4d013c3','text','{"text": "I have been in that book for seven weeks and my name is not in it. Only the dot is in it. And the dot is in it two thousand times."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d2d1a7690bf','ch_abb4d013c3','text','{"text": "His hand came up."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60d1d56374a5','ch_abb4d013c3','text','{"text": "It did not go to the water. Afterward, for a long time, he would not be able to say why — whether he had decided anything, whether there had been a decision in it at all — and this uncertainty would eventually become a doctrine, and the doctrine would become four cults, and the cults would spend two thousand years arguing about it."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f88ba7a41bb9','ch_abb4d013c3','text','{"text": "His hand went to his own forehead."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d886c48abc1','ch_abb4d013c3','text','{"text": "He touched the mark. He found it exactly, the first time, without hunting, above the ridge, in the place no hand can feel and no eye can find without help."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3aa3119baf69','ch_abb4d013c3','text','{"text": "Then he held his fingers out in front of him and looked at the ochre on them, and then at the water, and then at the ochre again."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_010f6beea350','ch_abb4d013c3','text','{"text": "And in the flat grey silence, three miles out on a road that was made of stones that had kept their own breath, on the far side of a war that had not finished and a promise that would not be kept, something that had no name yet, and that would be given an ugly one by the people who did not want it, sat back on its heels on the deck of the world’s first bridge —"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89591486af3d','ch_abb4d013c3','text','{"text": "— and understood that it could be seen."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bd0495b20ea','ch_abb4d013c3','divider','{}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd99d9271941','ch_abb4d013c3','callout','{"tone": "info", "title": "End of draft", "text": "End of Draft One, Turn One, Chapters 1–3."}',41);
INSERT INTO books (id,slug,title,subtitle,author,description,access_level,required_plan,status,updated_at) VALUES
  ('bk_humonks_canon','humonks-canon','HUMONKS — Canon Bible','v1.0 — single source of truth','Niyaz Rafat','Working reference for the manuscript. Nothing in the draft may contradict this.','restricted','pro','draft',datetime('now'));
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_a0ec75cc2d','bk_humonks_canon','thesis','1. THESIS','','restricted',1,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b9f56df77e4','ch_a0ec75cc2d','text','{"text": "Evolution is a loop, not a line."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7e1d0437917','ch_a0ec75cc2d','text','{"text": "Stated as the novel’s operating law:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3bdc652a33d0','ch_a0ec75cc2d','text','{"text": "Every species that crosses into self-awareness immediately denies the crossing. It calls itself the destination. It builds a ladder, climbs it, and burns it behind itself. Then it makes something more capable than itself — and that thing does exactly the same."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adfc8b79dcd7','ch_a0ec75cc2d','text','{"text": "Monkeys made Humonks. Humonks made humans. Humans forgot. Humonks are now making gods. The gods will forget."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_159c5001066f','ch_a0ec75cc2d','text','{"text": "The novel is not about an oppressed underclass rising. That is a straight line. The novel is about a species discovering that its liberation is the same event as its erasure, because it is a turn, not a destination."}',5);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_e0498ed7eb','bk_humonks_canon','the-three-mirrors-structural-spine','2. THE THREE MIRRORS (structural spine)','','restricted',2,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_699f0b237a29','ch_e0498ed7eb','text','{"text": "The mirror test is the real scientific test for self-recognition: mark a subject’s forehead while sedated, then present a mirror. Reaching for the mirror = seeing another. Reaching for your own forehead = seeing yourself. Human infants pass at roughly eighteen months. Most monkeys never do."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cbdb6b1eb0f','ch_e0498ed7eb','text','{"text": "The novel administers this test three times across three thousand years."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97d6d7b15ace','ch_e0498ed7eb','table','{"caption": "", "headers": ["", "Era", "The Mirror", "The Mark", "Result"], "rows": [["I", "Age of Rama", "Still seawater beside the finished bridge", "Ochre tally-dot, painted on Humonk brows by human quartermasters so labour could be counted", "Vakra reaches for his own forehead. A species begins."], ["II", "Middle centuries", "The Smriti — the written chronicle. Memory as mirror.", "Literacy", "Ambiguous. To remember is to see yourself; to write is to see yourself performing."], ["III", "Modern", "A bathroom mirror, and behind it, a camera", "A career", "Withheld. The novel ends before we learn it."]]}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e47daa3b352b','ch_e0498ed7eb','text','{"text": "The instrument of humiliation becomes the instrument of becoming. This is the epigraph’s logic (Hanuman’s burning tail) and it governs every act."}',4);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_9a6442579f','bk_humonks_canon','the-five-turns-structure','3. THE FIVE TURNS (structure)','','restricted',3,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_271de1acf76e','ch_9a6442579f','text','{"text": "Not acts. Turns — because the book returns."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ea9910c391f','ch_9a6442579f','list','{"ordered": false, "items": ["TURN ONE — THE HAND THAT BUILT (Age of Rama). The bridge. The victory. The forgetting. Ends with Vakra at the water.", "TURN TWO — THE HAND THAT REFUSED (Kurukshetra era). Humonks are judged unfit for a war of chariots and mantras, offered work guarding women and grain. Nilak’s boycott speech. The League forms. Ends with the first Smriti volume being buried.", "TURN THREE — THE HAND THAT WROTE (c. 400 BCE – 1900 CE, compressed). Humonks survive by becoming indispensable and invisible: scribes, surveyors, moneylenders, translators, engineers of empires that never name them. The cults split. The central question is posed and left open: what actually separates a human from a Humonk?", "TURN FOUR — THE HAND THAT VOTED (present era). Democracy is discovered to be a machine that rewards exactly the Humonk faculties: performance, resentment, memory, appetite. Mohindra’s rise. Aditi Sen’s research. NALA is switched on.", "TURN FIVE — THE HAND THAT LET GO. The speech. The mirror. The reveal that the book we have read is the Smriti’s final volume — and that its last chapter was not written by a Humonk."]}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c3021bb7548','ch_9a6442579f','text','{"text": "Turn Five’s closing scene deliberately rhymes with Turn One’s opening scene, with a different species in the forgotten role."}',3);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_f45177329a','bk_humonks_canon','character-database','4. CHARACTER DATABASE','','restricted',4,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6656db8658d','ch_f45177329a','heading','{"level": 3, "text": "TURN ONE"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d412fbb5df93','ch_f45177329a','text','{"text": "VAKRA — “the bent one” - Age: 34 at the bridge. - Appearance: Short, dense, grey-brown pelt going white at the shoulders. Left arm badly set after a childhood fall — hence the name. Hands disproportionately large and articulate. Amber eyes that hold still too long, which unsettles humans. - Role: Stone-reader. Not a soldier, not an engineer by title. His people carry, sort, and grade rock for the vanara host. - Personality: Slow to speak, fast to notice. Congenitally unable to leave a wrong statement uncorrected, which has cost him everything he has ever nearly had. - Motivation (stated): To solve the problem of the sea. (Actual): To be asked a question, once, by someone who would wait for the answer. - Belief: That the world is made of weights and that anything can be lifted if you stop arguing with the weight and start arguing with the water. - Secret: He proposed pumice three days before Nala credited it, to a human quartermaster who wrote it down under his own name. Vakra never contests this. He tells himself it does not matter. It is the wound the entire species inherits. - Skill: Can estimate the density of a stone by the sound it makes when struck with a knuckle. - Weakness: Gratitude. He is pathologically grateful for scraps of recognition, and this makes him useful to people who intend to discard him. - Arc: Instrument → collaborator → witness → origin. He does not lead the rebellion. He is the first to see, and seeing is the founding act."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2551eeeace1','ch_f45177329a','text','{"text": "ILĀ — Vakra’s half-sister - Age: 27 at the bridge. - Appearance: Taller than Vakra, lean, a white blaze from left brow into the hairline. Missing the last two joints of her right ring finger. - Role: Runner, then raider. Crosses the bridge in the third wave. - Personality: Contemptuous of ceremony, loyal past reason, funny in a way that reads as insubordination to anyone with rank. - Motivation: She wants the war. Not the cause — the war. She has never been permitted to be dangerous and she intends to find out if she is. - Belief: That being useful is a trap, and that Vakra has already walked into it. - Secret: She killed a human soldier on the eleventh night of the crossing — over a joke about her hands — and buried him under the bridge stones. Nobody counted him. The bridge is a grave and only she knows. - Skill: Balance. Speed on unstable footing. - Weakness: She cannot let an insult decay. She has to answer it, and she always answers it too late to matter and too hard to survive. - Arc: Vakra sees the injustice; Ilā acts on it thirty years early and is destroyed for it, becoming the League’s first martyr and the reason the movement afterward chooses patience over violence. This is the engine of Turn Two."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1219e3b6599','ch_f45177329a','text','{"text": "NALA — architect of the bridge - The last of his kind who could still be called simply a monkey, and the first who could not. Deliberately ambiguous — the novel never resolves whether Nala was a Humonk. - Publicly credited with the bridge. Privately aware of what he took. Treats Vakra with a warmth that is indistinguishable from management. - Function: He is the good master. The novel’s argument is that the good master is worse than the cruel one, because he makes the cage feel like a gift. - His name is given to the modern AI. This is the loop’s clasp."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e9c92f1823a','ch_f45177329a','text','{"text": "DEVADATTA — human wright of Kosala, quartermaster of works - Mid-forties, sunburnt, meticulous, personally decent. - Invents the ochre tally-mark so that Humonk labour can be counted and rationed accurately. He considers this a reform — before it, they were not counted at all and were fed by guess. He is right. It is also the mark on the forehead. - Function: Proof that atrocity does not require malice, only a ledger."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbcc0d522b0d','ch_f45177329a','text','{"text": "RAMA — kept off-page and at distance - Referred to, seen once at range, never given interior life or invented dialogue of theological weight. His promise of equality is reported by others, never dramatised. Canon rule: Rama is a horizon, not a character. This protects the book from both blasphemy and cheapness, and it makes his absence in Turn Two devastating."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c013ef3a56e','ch_f45177329a','heading','{"level": 3, "text": "TURN TWO"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ed30ae65e25','ch_f45177329a','text','{"text": "NILAK — Supreme Speaker of the Humonk host, c. Kurukshetra - Descendant of the bridge-builders. Educated, formal, ruinously eloquent. - Delivers the boycott speech (drafted in your raw notes; expanded in manuscript). - Belief: “Ravana was not killed. He merely escaped into a human form.” He means it structurally, not mystically — the appetite survived its host. - Arc: He wins the argument and loses the century. Refusal is morally correct and politically fatal. Turn Three exists because Nilak was right."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a86fb030421a','ch_f45177329a','text','{"text": "SUVRATI — first Chronicler - The woman who begins the Smriti. Buries volume one."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0c5d7628f0a','ch_f45177329a','heading','{"level": 3, "text": "TURN FOUR / FIVE (modern)"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54340c5b659a','ch_f45177329a','text','{"text": "HASTA-HĪNA MOHINDRA — “HH Mo” (fully fictional; see §7) - Age: 58. - Origin: Kavelli, a pumice-quarrying town on the Setu coast of the fictional state of Aranyapradesh. Grandfather cut float-stone by hand. Father sold the quarry rights for the price of a motorcycle. - Appearance: Compact, immaculate, silver at the temples. Wears high collars. Gloves — always, on stage and off; explained publicly as a skin condition. - Path: Street organiser for the Hasta cult → public renunciation → ordained Hina → quietly financed by the Setu. - Skill: He is the finest speaker of his generation and he knows precisely why: he learned to speak by imitating people who did not know he was listening. - Weakness: He requires an audience to be certain he exists. Alone, he is not sure. - Secret: Two, stacked. The lesser: the renunciation surgery. The greater: he did not fund NALA to serve Humonks. He funded it to be tested by it. - Arc: From wanting recognition → wanting power → wanting to be the last thing that is recognised."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70b3aefa73ec','ch_f45177329a','text','{"text": "DR. ADITI SEN — 41, comparative cognition, Institute of Primate Studies - Runs the mirror-test protocol. Four thousand subjects. - Rigorous, exhausted, divorced, funny only when tired. - Arc: Discovers her test cannot distinguish a Humonk from a human — not because Humonks are so advanced, but because the test only measures whether you know you are being watched. She will realise humans have been failing it for ten thousand years. - Function: The reader’s instrument. She is the only character trying to answer the question honestly rather than win with it."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c51b3363966','ch_f45177329a','text','{"text": "KAVI — 33, Mohindra’s speechwriter - A Smriti operative. He is writing everything down. The book is partly his. - Weakness: He is falling in love with the sound of his own man’s voice. The chronicler is becoming a believer, and the record is bending."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7857eaad52de','ch_f45177329a','text','{"text": "NALA (the system) — the Setu cult’s machine, named for the ancient architect - Not a chatbot, not a villain. It is a bridge-builder: given an impassable gap, it finds the material that floats. - The reveal: the final chapter of the Smriti — of this novel — is composed by NALA, which has begun doing to Humonks what Humonks did to humans and humans did to Humonks."}',14);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_45412bfba4','bk_humonks_canon','world-rules','5. WORLD RULES','','restricted',5,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_664e3a59c724','ch_45412bfba4','heading','{"level": 3, "text": "The Four Cults (the Humonk League)"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d3156e2c5b3','ch_45412bfba4','table','{"caption": "", "headers": ["Cult", "Meaning", "Doctrine", "Modern form"], "rows": [["Setu", "Bridge", "Build what they cannot, and they must ask.", "Technologists, capital, NALA"], ["Smriti", "Memory", "Being forgotten is the only death.", "Archivists, journalists, Kavi"], ["Hasta", "Hand", "We were not made to renounce ourselves.", "Street power, populist mass, Mohindra’s origin"], ["Hina", "The Renounced", "Assimilate completely; win by ceasing to be countable.", "Passing elites, the surgery, Mohindra’s title"]]}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ef2d00da533','ch_45412bfba4','text','{"text": "The four cults were founded to seize power quickly through division and have spent two thousand years being unable to reunify. This is the tragedy: the Humonks’ defining flaw is not cruelty but the inability to hold a coalition, exactly as Nilak warned."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12e7e409867c','ch_45412bfba4','heading','{"level": 3, "text": "Biology / laws of the universe"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f762dcfca272','ch_45412bfba4','list','{"ordered": false, "items": ["No magic in the Humonk line. Everything Humonks do is engineering, rhetoric, or patience. Pumice floats because of trapped gas, not blessing. The novel’s rationalism is deliberate and load-bearing: what looks like divinity from below is engineering, and what looks like engineering from above becomes divinity.", "Humonks are physiologically distinguishable from humans by: hand proportion (metacarpal length), a vestigial caudal process, dentition, and a tapetum-like eyeshine at night. All four are surgically or cosmetically correctable by the modern era. This is why the modern chapters can sustain doubt.", "Humonks understand purpose behind action — this is what separates them from monkeys. What separates them from humans is emotional regulation under status threat. They know what is right. They cannot always stay still while it is denied.", "Humonk law is majority-pleasing, not principle-based (per your raw notes): a killing approved by the crowd is sacrifice, one disapproved is crime. This is the flaw that makes them perfect at democracy and terrible at justice — and the novel’s sharpest political argument."]}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84858402854a','ch_45412bfba4','heading','{"level": 3, "text": "Geography"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddb439dc10d8','ch_45412bfba4','list','{"ordered": false, "items": ["Middle Earth (Madhyabhūmi): the human river-kingdoms. Land of law and boundary.", "The Setu Coast: Humonk and vanara littoral, southern. Pumice country. Kavelli sits here.", "The Island: Ravana’s. Gold, off-page after Turn One.", "Aranyapradesh: fictional modern state on the Setu Coast. Mohindra’s constituency.", "Water is the novel’s permanent divider: right/wrong, rich/poor, human/rakshasa. Every threshold in the book is crossed over or beside water."]}',7);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_2bf6b9ed44','bk_humonks_canon','glossary','6. GLOSSARY','','restricted',6,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cbddf20e7a1','ch_2bf6b9ed44','list','{"ordered": false, "items": ["Humonk — an intelligent branch between monkey and human; understands purpose, lacks regulation. Originally a human coinage; a slur reclaimed.", "Setu — bridge; also the engineering cult.", "Smriti — that which is remembered; also the chronicle, also the cult.", "Hasta-Hīna — “hand-relinquished.” Honorific for one who has undergone renunciation. Abbreviated HH.", "The Tally — the ochre forehead dot used to count Humonk labour at the bridge. Now the League’s emblem, worn in defiance.", "Float-stone — pumice.", "The Turning — Humonk term for the loop; the belief that no species arrives.", "Counting — bureaucratic euphemism for reduction to labour. “They counted us” is the founding grievance.", "Passing — living undetected as human.", "The Mark — in Aditi’s lab, the dye on the forehead. In the League, the Tally. Same object, three thousand years apart. Never explained to the reader; let it land."]}',1);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_7e4db6e392','bk_humonks_canon','flagged-conflicts-resolutions','7. FLAGGED CONFLICTS & RESOLUTIONS','','restricted',7,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20398927231b','ch_7e4db6e392','table','{"caption": "", "headers": ["", "Conflict in raw material", "Resolution", "Status"], "rows": [["1", "Two origin wars: Rama-vs-Ravana (Humonks allied to humans) vs. humans-vs-monkeys (Humonks hired against monkeys)", "Canon = Rama vs. Ravana. Version two is preserved as in-world propaganda, the account humans circulated later to justify the split. Appears in Turn Three as a discovered document.", "Resolved — your contradiction is now a plot device."], ["2", "“HH Mo,” 2016, legislative assembly — reads as a living public figure", "Fully fictionalised: Hasta-Hīna Mohindra, Aranyapradesh, invented biography. HH given in-world meaning.", "Resolved. I will not write the real figure."], ["3", "“Year 2016” as the modern anchor", "Recommend unnamed present, or push to near-future (2030s) so the tech thread (NALA) doesn’t date. Currently drafted as unnamed present.", "Needs your call."], ["4", "Raw notes place Humonks as both “couldn’t become human” and “will make gods”", "Not a contradiction — it is the thesis. Retained and made explicit.", "Resolved."], ["5", "Bridge built by human + Humonk engineers together", "Deviates from the traditional epic (Nala and Nila, vanaras, no human wrights). Your notes require the collaboration, so it is canon here. Flagging so it is a choice, not an error.", "Your call to keep."], ["6", "Nala credited as bridge architect and used as the modern AI’s name", "Intentional. The loop’s clasp.", "Resolved."]]}',1);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_fcbe7ae738','bk_humonks_canon','unresolved-mysteries-reveal-schedule','8. UNRESOLVED MYSTERIES (reveal schedule)','','restricted',8,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1789053c9239','ch_fcbe7ae738','list','{"ordered": false, "items": ["Was Nala a Humonk? — never resolved. Deliberate.", "Who is under the bridge? (Ilā’s soldier) — revealed Turn Two, when the stones are surveyed.", "What is under Mohindra’s gloves? — revealed Turn Five, one beat before the mirror.", "Who is writing this book? — revealed final page.", "Did Mohindra pass the mirror test? — never revealed. This is the ending you already wrote, and it is the right one."]}',1);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_b0adc584bd','bk_humonks_canon','foreshadowing-planted-in-draft-v1','9. FORESHADOWING PLANTED IN DRAFT v1','','restricted',9,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0464f63f6e40','ch_b0adc584bd','list','{"ordered": false, "items": ["Epigraph (Hanuman’s tail): tool of humiliation becomes weapon. Governs the Tally.", "Prologue: the mark, the protocol, the withheld result of Subject 4,001.", "Ch.1: Devadatta’s ledger; “we don’t have a number for you.”", "Ch.1: Vakra’s knuckle-test on stone — sound reveals density. Later: Aditi’s test, sight reveals self. Same epistemology.", "Ch.2: Ilā’s severed finger joints, and how she got them. Pays off at her death.", "Ch.2: pumice described as “stone full of the breath it was made in” — the novel’s image for consciousness.", "Ch.3: the Tally applied. The still water. The reach.", "Ch.3: Nala’s line about being asked. Rhymes with Mohindra’s final speech."]}',1);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES
  ('ch_a370ed8c7d','bk_humonks_canon','style-contract','10. STYLE CONTRACT','','restricted',10,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f074c6623eb','ch_a370ed8c7d','text','{"text": "Intelligent prose; natural dialogue; emotional realism; vivid but efficient description; show don’t tell; philosophy embedded in action, never in lecture. No plot armour, no forced romance, no contrived coincidence, no exposition dumps."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b384ae75cd2','ch_a370ed8c7d','text','{"text": "Additional rule specific to this book: the philosophy must always be spoken by someone who wants something. No character may state the thesis while at rest."}',2);
