  ('itm_bk_humonks_canon','sec_edu_humonks','humonks-canon','HUMONKS — Canon Bible','Working reference: thesis, turns, characters, world rules.','book','bk_humonks_canon','list','Internal','restricted','pro','Editorial reference. Access granted on request.',2,1,datetime('now'));
